mapper.update:
UPDATE scm_purchase_approval
SET po_id = #{poId},
    approval_level = #{approvalLevel},
    status = #{status},
    approver_id = #{approverId},
    comment = #{comment},
    approved_at = #{approvedAt}
WHERE tenant_id = #{tenantId}
  AND approval_id = #{approvalId}

mapper.select:
SELECT approval_id, tenant_id, po_id, approval_level, status, approver_id, comment, approved_at, created_at
FROM scm_purchase_approval WHERE tenant_id = #{tenantId} AND po_id = #{poId}
ORDER BY approval_level ASC, created_at ASC

